import styled from 'styled-components'

export const Card = styled.div`
  background-color: #fff;
  border-radius: 8px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  overflow: hidden;
  width: 100%;
  max-width: 472px;
  margin-bottom: 48px;
  display: flex;
  flex-direction: column;
  position: relative;
`

export const Imagem = styled.img`
  width: 100%;
  height: 200px;
  object-fit: cover;
`

export const Infos = styled.div`
  position: absolute;
  right: 0;
`

export const Descricao = styled.div`
  display: flex;
  flex-direction: column;

  &:nth-child(n + 3) {
    padding: 8px;
  }
`

export const Titulo = styled.h2`
  font-size: 18px;
  font-weight: bold;
  margin: 8px 0px;
`

export const Button = styled.button`
  background-color: #007bff;
  color: #fff;
  border: none;
  padding: 8px 16px;
  border-radius: 4px;
  cursor: pointer;
  font-size: 14px;
  margin-top: 16px;

  &:hover {
    background-color: #0056b3;
  }
`
